int decodeADPCMAudio(const uint8_t* encoded, int16_t* decoded) {
    int numChannels = getNumChannelsFromTrack(); // Assume this function retrieves the number of channels
    int samplesPerFrame = 2;
    int bytesWritten = 0;

    for (int ch = 0; ch < numChannels; ++ch) {
        ADPCMState state;
        initADPCMState(&state); // Assume this function initializes the ADPCM state
        uint8_t* channelData = const_cast<uint8_t*>(encoded) + ch;

        int16_t* channelDecoded = decoded + ch;

        while (*channelData != END_OF_STREAM) {
            int predictor = *channelData++;
            int index = *channelData++;

            for (int i = 0; i < samplesPerFrame; ++i) {
                int16_t sample = decodeSample(predictor, index, &state); // Assume this function decodes a sample
                *channelDecoded++ = sample;
            }

            bytesWritten += sizeof(int16_t) * samplesPerFrame;
        }
    }

    return bytesWritten;
}

